// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address baseToken, address nft, uint128 virtualBase, uint128 virtualNft, uint56 changeFee, uint16 feeRate, bytes32 root, bool useOracle, bool payRoyalties) public {
        vm.assume(feeRate <= 5000);
        vm.assume(baseToken != address(0));
        vm.assume(nft != address(0));
        vm.prank(address(this));
        c.initialize(baseToken, nft, virtualBase, virtualNft, changeFee, feeRate, root, useOracle, payRoyalties);
        assertTrue(c.initialized());
    }
}
